```cpp
#include "test_observer_cache_stats.h"

namespace test_reaction {

void CacheProbeNode::valueChanged(bool changed) {
    ObserverNode::valueChanged(changed);
}

CacheStatsSnapshot test_observer_cache_stats() {
    // 1. Create CacheProbeNode instances
    auto node1 = std::make_shared<CacheProbeNode>();
    auto node2 = std::make_shared<CacheProbeNode>();
    auto node3 = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(node1);
    graph.addNode(node2);
    graph.addNode(node3);

    // 4. Set up direct observer relationship
    // node1 observes node2
    graph.addObserver(node1, node2);

    // 5. Set up transitive observer relationship
    // node2 observes node3 (so node1 transitively observes node3)
    graph.addObserver(node2, node3);

    // 6. Create NodeSet to store collected observers
    reaction::NodeSet collectedObservers;

    // 7. Populate cache data
    // Trigger some graph traversals to populate the cache
    graph.collectObservers(node2, collectedObservers);
    collectedObservers.clear();
    graph.collectObservers(node3, collectedObservers);
    collectedObservers.clear();
    graph.collectObservers(node1, collectedObservers);

    // 8. Get cache statistics before cleanup
    auto cacheStats = graph.getCacheStats();
    size_t graphEntriesBeforeCleanup = cacheStats.graphStats.entryCount;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    cacheStats = graph.getCacheStats();
    size_t graphEntriesAfterCleanup = cacheStats.graphStats.entryCount;
    double graphHitRatioAfterCleanup = cacheStats.graphStats.hitRatio;

    // 11. Close all nodes
    graph.removeNode(node1);
    graph.removeNode(node2);
    graph.removeNode(node3);

    // 12. Return cache stats snapshot
    return CacheStatsSnapshot{
        graphEntriesBeforeCleanup,
        graphEntriesAfterCleanup,
        graphHitRatioAfterCleanup
    };
}

}  // namespace test_reaction
```

