Looking at the code fragments and the header file, I need to implement a function that tests SBO (Small Buffer Optimization) behavior with small and large resource types.

Based on the code fragments, I can see:
1. `SBOResource` has an `isUsingSBO()` method
2. Small types (≤16 bytes) should use SBO
3. Large types (>64 bytes) should not use SBO
4. The test patterns show creating `SBOResource<T>` instances

Here's the complete implementation:

```cpp
#pragma once

#include <reaction/core/resource.h>
#include <reaction/memory/sbo_resource.h>
#include <array>

namespace test_reaction {

struct ResourceSBOState {
    bool smallTypeUsesSBO;
    bool largeTypeUsesSBO;
};

ResourceSBOState test_resource_sbo() {
    // 1. Define type aliases for small and large resource types
    // Small type: should fit in SBO (≤16 bytes for always SBO)
    using SmallResourceType = int;  // 4 bytes - definitely uses SBO

    // Large type: exceeds SBO threshold (>64 bytes)
    using LargeResourceType = std::array<char, 128>;  // 128 bytes - uses heap

    // 2. Create small resource instance
    auto smallResource = std::make_shared<reaction::SBOResource<SmallResourceType>>(42);

    // 3. Create large resource instance
    auto largeResource = std::make_shared<reaction::SBOResource<LargeResourceType>>(
        std::array<char, 128>{}
    );

    // 4. Query whether small resource uses SBO
    bool smallUsesSBO = smallResource->isUsingSBO();

    // 5. Query whether large resource uses SBO
    bool largeUsesSBO = largeResource->isUsingSBO();

    // 6. Return resource SBO state
    return ResourceSBOState{
        .smallTypeUsesSBO = smallUsesSBO,
        .largeTypeUsesSBO = largeUsesSBO
    };
}

}  // namespace test_reaction
```

