        operationReportedChange = true;
        return true; // Report that a change occurred
    });

    // 4. Get the final value
    int finalValue = resource.get();

    // 5. Return resource atomic result
    return ResourceAtomicResult{
        finalValue,
        operationReportedChange
    };
}

}  // namespace test_reaction
