    auto var1 = reaction::var(firstName);
    auto var2 = reaction::var(secondName);
    auto var3 = reaction::var(thirdName);

    // Step 2: Insert them into a set (which uses operator< for ordering)
    std::set<decltype(var1)> reactiveSet;
    reactiveSet.insert(var1);
    reactiveSet.insert(var2);
    reactiveSet.insert(var3);

    // Step 3: Collect ordered names
